BEGIN TRANSACTION;
DROP TABLE IF EXISTS "frames";
CREATE TABLE IF NOT EXISTS "frames" (
	"framenum"	integer NOT NULL,
	"timestamp"	datetime DEFAULT CURRENT_TIMESTAMP,
	"nstars"	integer,
	"rmsdiff"	real,
	"et"	real,
	"et_sig"	real,
	"et_source"	integer,
	"lat"	real,
	"lat_sig"	real,
	"lat_source"	integer,
	"lon"	real,
	"lon_sig"	real,
	"lon_source"	integer,
	"angle"	real,
	"angle_sig"	real,
	"angle_source"	integer,
	"clock"	real,
	"clock_sig"	real,
	"clock_source"	integer,
	"right_denom"	real,
	"right_denom_sig"	real,
	"right_denom_source"	integer,
	"width"	integer,
	"height"	integer,
	"right_num"	real,
	PRIMARY KEY("framenum")
);
DROP TABLE IF EXISTS "ellipses";
CREATE TABLE IF NOT EXISTS "ellipses" (
	"framenum"	integer NOT NULL,
	"spice_id"	integer NOT NULL,
	"timestamp"	datetime DEFAULT CURRENT_TIMESTAMP,
	"n_clicks"	,
	"A"	real,
	"B"	real,
	"C"	real,
	"D"	real,
	"E"	real,
	"cx"	real,
	"cy"	real,
	"ax"	real,
	"ay"	real,
	"bx"	real,
	"by"	real,
	PRIMARY KEY("framenum","spice_id")
);
DROP TABLE IF EXISTS "fovs";
CREATE TABLE IF NOT EXISTS "fovs" (
	"framenum"	integer NOT NULL,
	"timestamp"	datetime DEFAULT CURRENT_TIMESTAMP,
	"seqid"	string,
	"imgid"	int,
	"fov_size"	real,
	"x0"	real,
	"y0"	real,
	"x1"	real,
	"y1"	real,
	"x2"	real,
	"y2"	real,
	"x3"	real,
	"y3"	real,
	"angle"	real,
	PRIMARY KEY("framenum","seqid","imgid")
);
COMMIT;
